import SwiftUI
import CoreGraphics
import Foundation

/// Official vendor brand marks, rendered as vector `Path`s from raw SVG path data so
/// they stay crisp at any size and tint with the app palette — no bitmap assets, no
/// asset-catalog entries. Each entry is the vendor's icon *glyph* (not the wordmark,
/// except where the wordmark **is** the brand's only mark — IBM, AI21), normalized to
/// fill a unit square.
///
/// A vendor with no bundled mark falls back to a tinted monogram (its initial in a
/// rounded square) — honest and legible, never a fake/mismatched logo.
struct VendorLogo: View {
    let vendor: String
    /// Fallback initial source when `vendor` is empty (an id no family matched) —
    /// pass the model name so the monogram is never a blank tile.
    var fallback: String = ""

    var body: some View {
        if let mark = VendorLogos.mark(for: vendor) {
            SVGPathShape(pathData: mark.path, viewBox: mark.viewBox)
                // Every bundled mark is authored `fill-rule="evenodd"`; counters and
                // holes disappear under the default non-zero winding.
                .fill(Tokens.text1, style: FillStyle(eoFill: true))
                .aspectRatio(1, contentMode: .fit)
        } else {
            Monogram(text: vendor.isEmpty ? fallback : vendor)
        }
    }
}

/// A monogram fallback for the long tail that has no vector mark worth shrinking —
/// community fine-tuners (TheDrummer, Sao10K) and the handful of labs whose logo is a
/// traced illustration that turns to mush at 15pt (Nous Research, Dolphin, Aion Labs).
///
/// Drawn as an outlined tile rather than a solid one so it reads as "no logo here"
/// beside the solid brand glyphs instead of competing with them. Everything scales off
/// the rendered side, since callers ask for 15/20/24pt from the same view.
private struct Monogram: View {
    let text: String
    /// `?` when even the fallback text is empty — an honest unknown, never a blank tile.
    private var initial: String {
        let c = text.first(where: { $0.isLetter || $0.isNumber }).map(String.init) ?? "?"
        return c.uppercased()
    }

    var body: some View {
        GeometryReader { geo in
            let side = min(geo.size.width, geo.size.height)
            RoundedRectangle(cornerRadius: side * 0.28, style: .continuous)
                .fill(Tokens.text1.opacity(0.05))
                .overlay(
                    RoundedRectangle(cornerRadius: side * 0.28, style: .continuous)
                        .strokeBorder(Tokens.text1.opacity(0.20), lineWidth: max(0.6, side / 22))
                )
                .overlay(
                    Text(initial)
                        .font(.sf(side * 0.5, weight: .semibold))
                        .foregroundStyle(Tokens.text1.opacity(0.70))
                )
                .frame(width: side, height: side)
        }
        .aspectRatio(1, contentMode: .fit)
    }
}

/// Draws an SVG `<path d="…">` string, scaled uniformly to fit the view's bounds while
/// preserving the source `viewBox` aspect ratio and centering the result.
struct SVGPathShape: Shape {
    let pathData: String
    let viewBox: CGSize

    /// Memoized `SVGPath.parse`. The model picker renders one `SVGPathShape` per row,
    /// and SwiftUI re-asks a shape for `path(in:)` on every hover/keyboard-focus move
    /// (each re-diffs the row), not just once per appearance — without a cache that
    /// re-runs the hand-rolled parser (arc-to-Bézier trig included) against the same
    /// unchanging `pathData` string on every call. Parsing is a pure function of
    /// `pathData`, so the unit-space result is safe to reuse forever; only the
    /// per-rect affine transform below still needs to run every time. Same rationale
    /// as `MarkdownParser.parseCache`: NSCache is thread-safe and purges under memory
    /// pressure, and the count limit comfortably covers the bundled mark table.
    private static let parseCache: NSCache<NSString, ParsedPath> = {
        let cache = NSCache<NSString, ParsedPath>()
        cache.countLimit = 64
        return cache
    }()

    /// NSCache values must be objects; a one-field box over the parsed, unit-space Path.
    private final class ParsedPath {
        let path: Path
        init(_ path: Path) { self.path = path }
    }

    func path(in rect: CGRect) -> Path {
        let key = pathData as NSString
        let raw: Path
        if let hit = Self.parseCache.object(forKey: key) {
            raw = hit.path
        } else {
            raw = SVGPath.parse(pathData)
            Self.parseCache.setObject(ParsedPath(raw), forKey: key)
        }
        guard viewBox.width > 0, viewBox.height > 0 else { return raw }
        let scale = min(rect.width / viewBox.width, rect.height / viewBox.height)
        let dx = (rect.width - viewBox.width * scale) / 2
        let dy = (rect.height - viewBox.height * scale) / 2
        let t = CGAffineTransform(translationX: dx, y: dy).scaledBy(x: scale, y: scale)
        return raw.applying(t)
    }
}

/// The bundled marks, keyed by the vendor names `ModelRatings.vendor(for:)` produces.
///
/// Path data is lifted from **@lobehub/icons-static-svg** (MIT), the icon set built for
/// exactly this — every AI model vendor, one optical weight, `fill-rule="evenodd"`,
/// `currentColor`. Multi-`<path>` icons are concatenated into a single `d` string;
/// their subpaths are disjoint, so the merged path rasterizes identically. Two marks
/// come from elsewhere: MiMo, whose lobehub icon is a "Xiaomi MiMo" wordmark — it
/// borrows Xiaomi's mi tile from Simple Icons (also evenodd-safe) instead — and
/// Poolside, which neither icon set carries, taken from the vendor's own favicon.
///
/// Deliberately *not* bundled: vendors whose logo is a traced illustration (Dolphin's
