/// A small SVG path-data parser: turns a `d="…"` string into a `Path`. Handles the
/// full command set Simple Icons and Wikimedia marks use — M/L/H/V/C/S/Q/T/A/Z in
/// both absolute and relative forms — including elliptical arcs (approximated as
/// cubic Béziers, which SwiftUI's `Path` draws natively). SVG's y-axis points down,
/// same as `Path`'s, so no flip is needed.
enum SVGPath {
    static func parse(_ d: String) -> Path {
        var path = Path()
        var scan = Scanner(d)
        var current = CGPoint.zero      // current point
        var start = CGPoint.zero        // subpath start (for Z)
        var lastCtrl: CGPoint?          // last cubic/quad control (for S/T smoothing)
        var lastCmd: Character = " "

        while let cmd = scan.command() {
            let rel = cmd.isLowercase
            switch cmd.uppercased().first! {
            case "M":
                var p = scan.point(rel: rel, from: current) ?? current
                path.move(to: p); current = p; start = p
                // Extra coordinate pairs after an M are implicit L commands.
                while let q = scan.point(rel: rel, from: current) {
                    path.addLine(to: q); current = q; p = q
                }
                lastCtrl = nil
            case "L":
                while let p = scan.point(rel: rel, from: current) {
                    path.addLine(to: p); current = p
                }
                lastCtrl = nil
            case "H":
                while let x = scan.number() {
                    let nx = rel ? current.x + x : x
                    let p = CGPoint(x: nx, y: current.y)
                    path.addLine(to: p); current = p
                }
                lastCtrl = nil
            case "V":
                while let y = scan.number() {
                    let ny = rel ? current.y + y : y
                    let p = CGPoint(x: current.x, y: ny)
                    path.addLine(to: p); current = p
                }
                lastCtrl = nil
            case "C":
                while let c1 = scan.point(rel: rel, from: current),
                      let c2 = scan.point(rel: rel, from: current),
                      let end = scan.point(rel: rel, from: current) {
                    path.addCurve(to: end, control1: c1, control2: c2)
                    lastCtrl = c2; current = end
                }
            case "S":
                while let c2 = scan.point(rel: rel, from: current),
                      let end = scan.point(rel: rel, from: current) {
                    let c1 = reflect(lastCtrl, over: current, smoothable: "CS".contains(lastCmd.uppercased()))
                    path.addCurve(to: end, control1: c1, control2: c2)
                    lastCtrl = c2; current = end
                }
            case "Q":
                while let c = scan.point(rel: rel, from: current),
                      let end = scan.point(rel: rel, from: current) {
                    path.addQuadCurve(to: end, control: c)
                    lastCtrl = c; current = end
                }
            case "T":
                while let end = scan.point(rel: rel, from: current) {
                    let c = reflect(lastCtrl, over: current, smoothable: "QT".contains(lastCmd.uppercased()))
                    path.addQuadCurve(to: end, control: c)
                    lastCtrl = c; current = end
                }
            case "A":
                while let rx = scan.number(), let ry = scan.number(),
                      let rot = scan.number(), let large = scan.flag(),
                      let sweep = scan.flag(), let end = scan.point(rel: rel, from: current) {
                    addArc(to: &path, from: current, to: end,
                           rx: rx, ry: ry, rotationDeg: rot,
                           largeArc: large, sweep: sweep)
                    current = end
                }
                lastCtrl = nil
            case "Z":
                path.closeSubpath(); current = start; lastCtrl = nil
            default:
                break
            }
            lastCmd = cmd
        }
        return path
    }

    /// Reflect the previous control point across the current point for S/T smoothing.
    /// When the previous command wasn't a matching curve, the reflection is the
    /// current point itself (per the SVG spec).
    private static func reflect(_ ctrl: CGPoint?, over p: CGPoint, smoothable: Bool) -> CGPoint {
        guard smoothable, let c = ctrl else { return p }
        return CGPoint(x: 2 * p.x - c.x, y: 2 * p.y - c.y)
    }

    /// Convert an SVG elliptical arc to one or more cubic Béziers appended to `path`.
    /// Follows the endpoint→center parameterization from the SVG implementation notes.
    private static func addArc(to path: inout Path, from p0: CGPoint, to p1: CGPoint,
                               rx rxIn: CGFloat, ry ryIn: CGFloat, rotationDeg: CGFloat,
                               largeArc: Bool, sweep: Bool) {
        var rx = abs(rxIn), ry = abs(ryIn)
        if rx == 0 || ry == 0 { path.addLine(to: p1); return }
        let phi = rotationDeg * .pi / 180
        let cosP = cos(phi), sinP = sin(phi)
        let dx = (p0.x - p1.x) / 2, dy = (p0.y - p1.y) / 2
        let x1p = cosP * dx + sinP * dy
        let y1p = -sinP * dx + cosP * dy
        // Scale radii up if they're too small to span the endpoints.
        let lambda = (x1p * x1p) / (rx * rx) + (y1p * y1p) / (ry * ry)
        if lambda > 1 { let s = sqrt(lambda); rx *= s; ry *= s }
        let sign: CGFloat = (largeArc != sweep) ? 1 : -1
        let num = max(rx*rx*ry*ry - rx*rx*y1p*y1p - ry*ry*x1p*x1p, 0)
        let den = rx*rx*y1p*y1p + ry*ry*x1p*x1p
        let co = sign * sqrt(den == 0 ? 0 : num / den)
        let cxp = co * rx * y1p / ry
        let cyp = -co * ry * x1p / rx
        let cx = cosP * cxp - sinP * cyp + (p0.x + p1.x) / 2
        let cy = sinP * cxp + cosP * cyp + (p0.y + p1.y) / 2
        func angle(_ ux: CGFloat, _ uy: CGFloat, _ vx: CGFloat, _ vy: CGFloat) -> CGFloat {
            let dot = ux*vx + uy*vy
            let len = sqrt((ux*ux+uy*uy)*(vx*vx+vy*vy))
            var a = acos(min(max(len == 0 ? 1 : dot/len, -1), 1))
            if ux*vy - uy*vx < 0 { a = -a }
            return a
        }
        let theta1 = angle(1, 0, (x1p - cxp)/rx, (y1p - cyp)/ry)
        var delta = angle((x1p - cxp)/rx, (y1p - cyp)/ry, (-x1p - cxp)/rx, (-y1p - cyp)/ry)
        if !sweep && delta > 0 { delta -= 2 * .pi }
        if sweep && delta < 0 { delta += 2 * .pi }
        // Split into ≤90° segments; each becomes one cubic.
        let segs = max(Int(ceil(abs(delta) / (.pi / 2))), 1)
        let segAngle = delta / CGFloat(segs)
        let t = 4.0 / 3.0 * tan(segAngle / 4)
        var ang = theta1
        for _ in 0..<segs {
            let cosA = cos(ang), sinA = sin(ang)
            let cosB = cos(ang + segAngle), sinB = sin(ang + segAngle)
            func pt(_ ca: CGFloat, _ sa: CGFloat) -> CGPoint {
                CGPoint(x: cx + cosP * rx * ca - sinP * ry * sa,
                        y: cy + sinP * rx * ca + cosP * ry * sa)
            }
            let e = pt(cosB, sinB)
            let c1 = CGPoint(x: cx + cosP*(rx*(cosA - t*sinA)) - sinP*(ry*(sinA + t*cosA)),
                             y: cy + sinP*(rx*(cosA - t*sinA)) + cosP*(ry*(sinA + t*cosA)))
            let c2 = CGPoint(x: cx + cosP*(rx*(cosB + t*sinB)) - sinP*(ry*(sinB - t*cosB)),
                             y: cy + sinP*(rx*(cosB + t*sinB)) + cosP*(ry*(sinB - t*cosB)))
            path.addCurve(to: e, control1: c1, control2: c2)
            ang += segAngle
        }
    }
}

/// A forward scanner over SVG path-data: pulls commands, numbers, coordinate pairs,
/// and arc flags, tolerating the spec's flexible whitespace/comma separators and
/// leading signs. Not `Foundation.Scanner` — a tiny purpose-built one over the chars.
private struct Scanner {
    private let chars: [Character]
    private var i = 0
    init(_ s: String) { chars = Array(s) }

    private mutating func skipSeparators() {
        while i < chars.count, chars[i] == " " || chars[i] == "," || chars[i] == "\n"
                || chars[i] == "\t" || chars[i] == "\r" { i += 1 }
    }

    mutating func command() -> Character? {
        skipSeparators()
        guard i < chars.count else { return nil }
        let c = chars[i]
        if c.isLetter { i += 1; return c }
        return nil
    }

    mutating func number() -> CGFloat? {
        skipSeparators()
        guard i < chars.count else { return nil }
        let startAdvance = i
        var s = ""
        if chars[i] == "+" || chars[i] == "-" { s.append(chars[i]); i += 1 }
        var sawDigit = false, sawDot = false
        while i < chars.count {
            let c = chars[i]
            if c.isNumber { s.append(c); i += 1; sawDigit = true }
            else if c == "." && !sawDot { s.append(c); i += 1; sawDot = true }
            else if (c == "e" || c == "E"), sawDigit {
                s.append(c); i += 1
                if i < chars.count, chars[i] == "+" || chars[i] == "-" { s.append(chars[i]); i += 1 }
            } else { break }
        }
        guard sawDigit, let v = Double(s) else { i = startAdvance; return nil }
        return CGFloat(v)
    }

    mutating func point(rel: Bool, from current: CGPoint) -> CGPoint? {
        let save = i
        guard let x = number(), let y = number() else { i = save; return nil }
        return rel ? CGPoint(x: current.x + x, y: current.y + y) : CGPoint(x: x, y: y)
    }

    /// Arc flags are a single `0`/`1` char, which may abut the next number without a
    /// separator (`…0 1 …` or `…011…`), so they're read one digit at a time.
    mutating func flag() -> Bool? {
        skipSeparators()
        guard i < chars.count else { return nil }
        let c = chars[i]
        if c == "0" { i += 1; return false }
        if c == "1" { i += 1; return true }
        return nil
    }
}
